import 'dart:async';
Future<void> main() async {
  final c = StreamController<int>();
  final it = StreamIterator(c.stream);
  c.add(1);
  print(await it.moveNext());
  final f1 = it.cancel();
  final f2 = it.cancel(); // double cancel
  final f3 = it.cancel();
  await f1; await f2; await f3;
  print('double cancel OK');
  // cancel while generator suspended awaiting input
  final it2 = StreamIterator(gen(c));
  final mv = it2.moveNext();
  final cf = it2.cancel();
  await c.close();
  await cf;
  print(await mv == false);
  print('lazy cancel completed after close');
}
Stream<int> gen(Stream<int> src) async* {
  await for (final e in src) { yield e; }
}
